-- Bank soal untuk seeder (src/server/db/seed.ts).
-- File ini dirawat manual dan jadi satu-satunya sumber kebenaran untuk seluruh
-- kartu yang di-seed: pertanyaan klasik `q-*` dan kartu flag `f-*`.
-- Tidak ada generator — `src/data/questions.ts` sudah tidak ada lagi, jadi
-- edit langsung di file ini. Apostrof di dalam literal ditulis ganda ('').
on conflict (id) do update set
  text_id = excluded.text_id,
  text_en = excluded.text_en,
  category = excluded.category,
  depth = excluded.depth,
  bias = excluded.bias,
  for_group = excluded.for_group,
  type = excluded.type;

